def solve_direct(A, k=5, ncv=20, tol=0, maxiter=None, v0=None):
    N=A.shape[0]
    if maxiter is None: maxiter=N*200
    if v0 is None: v0=np.ones(N, dtype=A.dtype)
    matvec = A._matmul_vector
    params = _UnsymmetricArpackParams(N, k, 'd', matvec, ncv=ncv, v0=v0, maxiter=maxiter, tol=tol)
