import numpy as np, time
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams
from scipy.sparse.linalg import eigs
from reference import Task

task = Task()
problems=[task.generate_problem(n=300, random_seed=s) for s in range(6)]
refs=[task.solve(p) for p in problems]

def solve(A, k_poly=12, ncv=30, degree=2, tol=0):
    N=A.shape[0]
    mv=A._matmul_vector
    if degree==2:
        def op(x):
            return mv(mv(x))
    elif degree==3:
        def op(x):
            return mv(mv(mv(x)))
    else:
        op=mv
    v0=np.ones(N)
    params=_UnsymmetricArpackParams(N, k_poly, 'd', op, ncv=ncv, v0=v0, maxiter=N*100, tol=tol)
    while not params.converged:
        params.iterate()
    ev, vec = params.extract(True)
    # Rayleigh of A for each
    rays=[]
    for j in range(vec.shape[1]):
        v=vec[:,j]
        Av=mv(v)
        lam=np.vdot(v, Av)/np.vdot(v,v)
        rays.append(lam)
    rays=np.array(rays)
    order=np.argsort(-np.abs(rays))[:5]
    return rays[order], vec[:,order]

def check(vecs, ref):
    for i in range(5):
        exp=ref[i]
        sim=abs(np.vdot(exp, vecs[:,i]))/(np.linalg.norm(exp)*np.linalg.norm(vecs[:,i]))
        if sim<1-1e-6:
            return False
    return True

tref=0
for p in problems:
    t0=time.perf_counter(); task.solve(p); tref+=time.perf_counter()-t0
print('ref', round(tref,3))

for degree in [2,3]:
  for k_poly in [8,10,12,16]:
    for ncv in [k_poly+8, k_poly+15, max(2*k_poly, 24)]:
        times=[]; bad=0
        for p, ref in zip(problems, refs):
            t0=time.perf_counter()
            try:
                rays, vecs = solve(p['matrix'], k_poly=k_poly, ncv=ncv, degree=degree)
            except Exception:
                bad+=1; times.append(time.perf_counter()-t0); continue
            times.append(time.perf_counter()-t0)
            if not check(vecs, ref): bad+=1
        print(f'deg={degree} k={k_poly} ncv={ncv} total={sum(times):.3f} bad={bad} sp={tref/max(sum(times),1e-9):.2f}')
