    N=A.shape[0]; mv=A._matmul_vector
    def op(x):
        y=x
        for _ in range(degree): y=mv(y)
        return y
    params=_UnsymmetricArpackParams(N, k_poly, 'd', op, ncv=ncv, v0=np.ones(N), maxiter=N*150, tol=tol)
