import numpy as np, time
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams
from reference import Task
task = Task()
problems=[task.generate_problem(n=300, random_seed=s) for s in range(8)]
refs=[task.solve(p) for p in problems]

def solve(A, degree, k_poly, tol1):
    N=A.shape[0]; mv=A._matmul_vector
    def op(x):
        y=x
        for _ in range(degree): y=mv(y)
        return y
    ncv1=2*k_poly+1
    params=_UnsymmetricArpackParams(N, k_poly, 'd', op, ncv=ncv1, v0=np.ones(N), maxiter=N*100, tol=tol1)
    while not params.converged: params.iterate()
    ev, vec = params.extract(True)
    AV=A@vec
    rays=np.sum(vec.conj()*AV, axis=0)/np.sum(np.abs(vec)**2, axis=0)
    j=int(np.argmax(np.abs(rays)))
    v0=np.real(vec[:,j]); nrm=np.linalg.norm(v0)
    if nrm==0: v0=np.ones(N); nrm=np.linalg.norm(v0)
    v0=v0/nrm
    params=_UnsymmetricArpackParams(N, 5, 'd', mv, ncv=20, v0=v0, maxiter=N*200, tol=0)
    while not params.converged: params.iterate()
    ev, vec = params.extract(True)
    idx=np.argsort(-np.abs(ev), kind='mergesort')
    return [vec[:,j] for j in idx], params.arpack_dict['iter']

def check(sol, ref):
    for c, e in zip(sol, ref):
        if abs(np.vdot(e, c))/(np.linalg.norm(e)*np.linalg.norm(c)) < 1-1e-6:
            return False
    return True

task.solve(problems[0])
t0=time.perf_counter()
for p in problems: task.solve(p)
tref=time.perf_counter()-t0
print('ref', round(tref,3), flush=True)
for degree,kp,tol1 in [(4,8,1e-6),(6,8,1e-6),(4,10,1e-6),(6,10,1e-6),(8,8,1e-6),(4,8,1e-4),(6,6,1e-6),(10,6,1e-6),(6,8,1e-4),(4,12,1e-4)]:
    t0=time.perf_counter(); bad=0; fails=0; iters=[]
    for p, ref in zip(problems, refs):
        try:
            sol,it=solve(p['matrix'], degree, kp, tol1)
        except Exception:
            fails+=1; continue
        iters.append(it)
        if not check(sol, ref): bad+=1
    dt=time.perf_counter()-t0
    print(f'deg={degree} k={kp} tol={tol1:.0e} t={dt:.3f} bad={bad} fails={fails} meanit={np.mean(iters) if iters else -1:.0f} sp={tref/dt:.2f}', flush=True)
EOF"}

